sys_script_include.script:
var EventUtilsUIPage = Class.create();
EventUtilsUIPage.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getUpcomingEvents: function() {
        var eventList = [];
        var eventGR = new GlideRecord('x_1610434_event_0_event_record'); // Replace with actual table name

        eventGR.addQuery('event_date', '>=', gs.daysAgoStart(0)); // Fetch future events
        eventGR.addQuery('status', '!=', 'Cancelled'); // Ignore cancelled events
        eventGR.orderBy('event_date'); // Sort by date
        eventGR.query();

        while (eventGR.next()) {
            eventList.push({
                name: eventGR.getValue('event_name'),
                date: eventGR.getValue('event_date'),
                location: eventGR.getDisplayValue('location'),
                status: eventGR.getValue('status'),
				contact: eventGR.getValue('contact_person')
            });
        }

        return JSON.stringify(eventList);
    },
    type: 'EventUtilsUIPage'
});
